func TestDeletedTodoStaysAbsentWhenStoreReopens(t *testing.T) {
	databasePath := filepath.Join(t.TempDir(), "todos.db")
	store, err := NewStore(databasePath)
	if err != nil {
		t.Fatal(err)
	}
	created, err := store.Create(todoInput{Title: "Delete permanently"})
	if err != nil {
		t.Fatal(err)
	}
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	reopened, err := NewStore(databasePath)
	if err != nil {
		t.Fatal(err)
	}
	persisted, err := reopened.Get(created.ID)
	if err != nil {
		t.Fatalf("created todo did not persist: %v", err)
	}
	if persisted.Title != created.Title {
		t.Fatalf("persisted title = %q, want %q", persisted.Title, created.Title)
	}
	handler := newAPIHandler(reopened)
	response := httptest.NewRecorder()
	handler.ServeHTTP(response, httptest.NewRequest(http.MethodDelete, "/api/todos/"+strconv.FormatInt(created.ID, 10), nil))
	if response.Code != http.StatusNoContent || response.Body.Len() != 0 {
		t.Fatalf("DELETE status/body = %d/%q, want 204/empty", response.Code, response.Body.String())
	}
	if err := reopened.Close(); err != nil {
		t.Fatal(err)
	}

	reopened, err = NewStore(databasePath)
	if err != nil {
		t.Fatal(err)
	}
	defer reopened.Close()
	if _, err := reopened.Get(created.ID); err != errTodoNotFound {
		t.Fatalf("deleted todo after reopen error = %v, want %v", err, errTodoNotFound)
	}
	todos, err := reopened.List()
	if err != nil {
		t.Fatal(err)
	}
	if len(todos) != 0 {
		t.Fatalf("deleted todo remains after reopen: %+v", todos)
	}
}

func newTestStore(t *testing.T) *Store {
	t.Helper()
	store, err := NewStore(filepath.Join(t.TempDir(), "todos.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := store.Close(); err != nil {
			t.Errorf("close store: %v", err)
		}
	})
	return store
}

func performRequest[T any](t *testing.T, handler http.Handler, method, path, body string, expectedStatus int) T {
	t.Helper()

	request := httptest.NewRequest(method, path, bytes.NewBufferString(body))
	if body != "" {
		request.Header.Set("Content-Type", "application/json")
	}
	response := httptest.NewRecorder()
	handler.ServeHTTP(response, request)

	if response.Code != expectedStatus {
		t.Fatalf("%s %s status = %d, want %d; body: %s", method, path, response.Code, expectedStatus, response.Body.String())
	}

	var result T
	if err := json.NewDecoder(response.Body).Decode(&result); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	return result
}

